        /** If existing, the URL of the repository (e.g. a GitHub repository). */
        repositoryURL?: Maybe<Scalars["URL"]["output"]>;
        /** IMSProjects this Trackable is synced to and from. */
        syncsTo: ImsProjectConnection;
